def _get_user_permissions(self, user_obj, obj=None):
    """
    Return a set of permissions for the given user object from the user.
    """
    if not user_obj.is_active or obj is not None:
        return set()

    perm_cache_name = "_user_perm_cache"
    if not hasattr(user_obj, perm_cache_name):
        perms = user_obj.user_permissions.all().values_list("codename", flat=True)
        setattr(user_obj, perm_cache_name, set(perms))
    return getattr(user_obj, perm_cache_name)


